mapper.sql:
	FROM codegroup a
	WHERE 1=1
		AND a.ifcgdelNy=0

		AND a.ifcguseNy = #{shUseNy}
        AND a.ifcgdelNy = #{shDelNy}



					AND a.datetimestart BETWEEN #{shDateStartdb} AND #{shDateEnddb}

					AND a.datetimeend BETWEEN #{shDateStartdb} AND #{shDateEnddb}



            AND a.ifcgseq = #{shValue}
            AND a.ifcgname LIKE CONCAT('%',#{shValue},'%')
